211	export function getLatestNews(options) {
212	  var params = options || {}
213	  var categories = params.categories && params.categories.length ? params.categories.join(",") : ""
214	
215	  var query = encodeQuery({
216	    language: "zh",
217	    country: "CN",
218	    category: categories,
219	    page_size: params.pageSize || 20,
220	    apiKey: CURRENTS_API_KEY.trim()
221	  })
222	
223	  return request({
224	    url: CURRENTS_BASE_URL + "/latest-news?" + query
225	  }).then(function (data) {
226	    if (!data || data.status !== "ok" || !data.news) {
227	      return []
228	    }
229	    var filtered = data.news
230	      .map(function (item) {
231	        if (!item) return null
232	        var source = item.author || "未知来源"
233	        var title = item.title || "未命名新闻"
234	        var desc = item.description || "暂无摘要"
235	        return {
236	          id: item.id || "",
237	          title: title,
238	          description: desc,
239	          source: source,
240	          url: item.url || "",
241	          published: item.published || ""
242	        }
243	      })
244	      .filter(function (item) {
245	        return item && item.description && item.description !== item.title
246	      })
247	    return filtered
248	  })
249	}
